import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';

class ScriptedRoundProvider implements AIProvider {
  private roundIndex = 0;

  constructor(private readonly rounds: MessageChunk[][]) {}

  async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
    yield* this.rounds[this.roundIndex++] ?? [];
  }

  async generateStructured<T>(): Promise<T> {
    return {} as T;
  }
}

export const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => new ScriptedRoundProvider(rounds);

